"Вопрос: "+(r.question||"не указан"),
"Карты по позициям:\n"+briefs.join("\n\n"),
"Дополнительные карты: "+((r.jumpers||[]).map(x=>{const m=meanings[x.card.id]||{};return x.card.name+" — "+(m.core_theme||"")}).join("; ")||"нет")
