const settingsStorageKey="manara-settings-v1",themeDefaults={sea:"#effafd",sand:"#3b302b",forest:"#eef6ed",pastel:"#403242",transparent:"#f7f0f4"};
function readSettings(){try{return JSON.parse(localStorage.getItem(settingsStorageKey)||"{}")}catch{return {}}}
function applySettings(settings){const theme=["sea","sand","forest","pastel","transparent"].includes(settings.theme)?settings.theme:"sand",size=Math.max(14,Math.min(24,Number(settings.fontSize)||16)),color=/^#[0-9a-f]{6}$/i.test(settings.fontColor||"")?settings.fontColor:themeDefaults[theme];document.body.dataset.theme=theme;document.documentElement.style.setProperty("--app-font-size",`${size}px`);document.body.style.setProperty("--ink",color);if($("setting-theme"))$("setting-theme").value=theme;if($("setting-font-size"))$("setting-font-size").value=String(size);if($("setting-font-color"))$("setting-font-color").value=color;if($("font-size-value"))$("font-size-value").textContent=`${size} px`;if($("font-color-value"))$("font-color-value").textContent=color.toUpperCase()}
