function updateCountLimit(){const max=Math.max(0,78-currentSpread().positions.length);$("jumper-count").max=String(max);if(Number($("jumper-count").value)>max)$("jumper-count").value=String(max);$("jumper-help").textContent=`Для этой схемы доступно до ${max} дополнительных карт.`}
