function renderManualCards(){const box=$("manual-cards");if($("draw-mode").value!=="manual"){box.classList.add("hidden");return}box.classList.remove("hidden");const spread=currentSpread(),count=extraCount(),previous=Object.fromEntries([...box.querySelectorAll("select")].map(x=>[x.id,x.value])),rows=spread.positions.map((p,i)=>({id:`manual-position-${i}`,label:`${i+1}. ${p.label}`,majorOnly:$("spread").value==="royal"&&i===0,minorOnly:$("spread").value==="royal"&&i>0}));for(let i=0;i<count;i++)rows.push({id:`manual-jumper-${i}`,label:`Дополнительная карта ${i+1}`});box.innerHTML=`<h3>Введите карты физического расклада</h3>${rows.map(row=>{const options=cards.filter(c=>row.majorOnly?c.group==="major":row.minorOnly?c.group!=="major":true);return `<label class="field-label" for="${row.id}">${esc(row.label)}</label><select class="search manual-card-select" id="${row.id}"><option value="">Выберите карту</option>${options.map(c=>`<option value="${esc(c.id)}" ${previous[row.id]===c.id?"selected":""}>${esc(c.name)}</option>`).join("")}</select>`}).join("")}`}
