document.addEventListener("click",async e=>{
const btn=e.target.closest("[data-generate-local-reading]");if(!btn)return;
const status=$("local-ai-status"),input=$("local-ai-endpoint");if(!status||!input)return;
const endpoint=input.value.trim(),modelInput=$("local-ai-model"),model=(modelInput?.value||"Qwen3.5-4B").trim();
try{
const url=new URL(endpoint),host=url.hostname.replace(/^\\[|\\]$/g,"");
if(!["127.0.0.1","localhost","::1"].includes(host)||!["http:","https:"].includes(url.protocol))throw new Error("Укажите адрес локального сервера (localhost или 127.0.0.1).");
localStorage.setItem("manara-local-ai-endpoint",url.href);localStorage.setItem("manara-local-ai-model",model);
const history=JSON.parse(localStorage.getItem("manara-history")||"[]"),record=history.find(x=>x.id===btn.dataset.readingId);
if(!record)throw new Error("Не удалось найти этот расклад в истории.");
btn.disabled=true;status.textContent="Локальная модель пишет разбор. Это может занять несколько минут.";
const response=await fetch(url.href,{method:"POST",credentials:"omit",headers:{"Content-Type":"application/json"},body:JSON.stringify({model,messages:[{role:"system",content:"Ты — бережный, ясный и вдумчивый автор трактовок Таро Манара. Следуй инструкциям пользователя и используй только переданные значения карт. Не утверждай, что знаешь будущее или мысли третьих лиц."},{role:"user",content:makeLocalReadingPrompt(record)}],temperature:0.65,max_tokens:Math.min(3600,900+record.cards.length*480)})});
if(!response.ok)throw new Error("Локальный сервер ответил с ошибкой "+response.status+".");
const data=await response.json(),content=data.choices?.[0]?.message?.content;
const answer=typeof content==="string"?content:Array.isArray(content)?content.map(x=>x.text||"").join(""):"";
if(!answer.trim())throw new Error("Сервер не вернул текст. Проверьте, что загружена чат-модель.");
record.localAiReading=answer.trim();localStorage.setItem("manara-history",JSON.stringify(history));renderReading(record);
}catch(error){if(status)status.textContent="Не удалось получить разбор: "+(error?.message||"проверьте локальный сервер и разрешение CORS").replace(/^Failed to fetch$/,"сервер недоступен или браузер заблокировал запрос (CORS).");if(btn)btn.disabled=false}
});
